INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT149-S4-Q16$batch05$, 149, 4, 16, $batch05$Must Be True (fill in the blank)$batch05$, $batch05$Economist: Currently, many countries rely primarily on taxing income to fund government expenditures. But taxing income does nothing to promote savings and investment. Taxing consumption, on the other hand, would encourage savings. The most important challenge facing these countries is improving their economies, and the only way to accomplish this is to increase their savings rates.$batch05$, $batch05$Which one of the following most logically completes the economist’s argument?$batch05$, $batch05$D$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=149 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$most governments should stop taxing savings and investment$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$the economies of countries will rapidly improve if their governments adopt tax policies that encourage savings and investment$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$in most countries taxes on consumption alone could raise adequate revenues to fund government expenditures$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$the tax laws of many countries should be revised to focus on taxing consumption rather than income$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$it is detrimental to the economic improvement of any country to continue to tax income$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The blank: the policy the economist's facts point to.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Improving their economies is these countries' biggest challenge. The only way to do it is to raise savings rates. Taxing income does nothing for savings. Taxing consumption would encourage them.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Line the facts up and the conclusion almost writes itself. The goal needs higher savings. Income taxes do not help with that, and consumption taxes do. So these countries should move from taxing income to taxing consumption. A completion answer should land exactly where the evidence points, and go no further.$batch05$), (3, $batch05$Goal$batch05$, $batch05$These countries should shift from taxing income toward taxing consumption.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The economist never says anyone taxes savings. Stopping a tax that was never mentioned does not follow.$batch05$), ($batch05$B$batch05$, $batch05$Higher savings are the *only* way to improve, but that does not make them a guarantee of improvement, let alone a rapid one.$batch05$), ($batch05$C$batch05$, $batch05$Whether consumption taxes alone could pay for everything is never discussed.$batch05$), ($batch05$D$batch05$, $batch05$This is the conclusion the evidence builds toward: switch the tax focus to the one that encourages savings. Every piece of the argument supports it, and it claims nothing extra.$batch05$), ($batch05$E$batch05$, $batch05$"Detrimental" to "any country" goes well past the evidence. The economist only says income taxes do nothing for savings, not that they actively hurt every economy.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT149-S4-Q16$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
